import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百二十五章 四界的吸引力是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/125第一百二十五章 四界的吸引力是什么.md","filePath":"meditation/巴利文大藏经/125第一百二十五章 四界的吸引力是什么.md"}'),o={name:"meditation/巴利文大藏经/125第一百二十五章 四界的吸引力是什么.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百二十五章-四界的吸引力是什么" tabindex="-1">第一百二十五章 四界的吸引力是什么？ <a class="header-anchor" href="#第一百二十五章-四界的吸引力是什么" aria-label="Permalink to &quot;第一百二十五章 四界的吸引力是什么？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部14相应31经/正觉以前经(界相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，如来还没有证悟无上正等正觉之前，还是菩萨的时候，曾经想到这样的问题：「地界（地界解释，见第一百二十四章）的吸引力是什么？对地界渴爱、热爱的滋味是什么？地界的祸患是什么？如何才能从地界中解脱出来？</p><p>水界（水界解释，见第一百二十四章）的吸引力是什么？对水界渴爱、热爱的滋味是什么？水界的祸患是什么？如何才能从水界中解脱出来？</p><p>火界（火界解释，见第一百二十四章）的吸引力是什么？对火界渴爱、热爱的滋味是什么？火界的祸患是什么？如何才能从火界中解脱出来？</p><p>风界（风界解释，见第一百二十四章）的吸引力是什么？对风界渴爱、热爱的滋味是什么？风界的祸患是什么？如何才能从风界中解脱出来？」</p><p>弟子们，如来过去还是菩萨的时候就在想这样的问题，如来当时是这样为自己解答这个问题的：「以地界为前提条件就会对接触到的地界生起快乐、喜悦，这就是地界的吸引力，这就是对地界渴爱、热爱的滋味。</p><p>然而地界是无法永远存在的，是无法永恒保持不变的，是随时在变化的，因为地界是随时在变化的，是无法永远存在的，是无法永恒保持不变的，所以当地界发生变化的时候，比如当地界衰败、灭亡、消失的时候就会最终导致痛苦，这就是地界的祸患。</p><p>控制降伏对地界的贪求，除灭对地界的贪爱，不对地界生起贪欲，就不会被地界束缚捆绑，就从地界中解脱了出来。</p><p>以水界为前提条件就会对接触到的水界生起快乐、喜悦，这就是水界的吸引力，这就是对水界渴爱、热爱的滋味。</p><p>然而水界是无法永远存在的，是无法永恒保持不变的，是随时在变化的，因为水界是随时在变化的，是无法永远存在的，是无法永恒保持不变的，所以当水界发生变化的时候，比如当水界衰败、灭亡、消失的时候就会最终导致痛苦，这就是水界的祸患。</p><p>控制降伏对水界的贪求，除灭对水界的贪爱，不对水界生起贪欲，就不会被水界束缚捆绑，就从水界中解脱了出来。</p><p>以火界为前提条件就会对接触到的火界生起快乐、喜悦，这就是火界的吸引力，这就是对火界渴爱、热爱的滋味。</p><p>然而火界是无法永远存在的，是无法永恒保持不变的，是随时在变化的，因为火界是随时在变化的，是无法永远存在的，是无法永恒保持不变的，所以当火界发生变化的时候，比如当火界衰败、灭亡、消失的时候就会最终导致痛苦，这就是火界的祸患。</p><p>控制降伏对火界的贪求，除灭对火界的贪爱，不对火界生起贪欲，就不会被火界束缚捆绑，就从火界中解脱了出来。</p><p>以风界为前提条件就会对接触到的风界生起快乐、喜悦，这就是风界的吸引力，这就是对风界渴爱、热爱的滋味。</p><p>然而风界是无法永远存在的，是无法永恒保持不变的，是随时在变化的，因为风界是随时在变化的，是无法永远存在的，是无法永恒保持不变的，所以当风界发生变化的时候，比如当风界衰败、灭亡、消失的时候就会最终导致痛苦，这就是风界的祸患。</p><p>控制降伏对风界的贪求，除灭对风界的贪爱，不对风界生起贪欲，就不会被风界束缚捆绑，就从风界中解脱了出来。」</p><p>弟子们，如来过去还是菩萨的时候，如果没有证悟地界、水界、火界、风界这四界的吸引力是什么；对四界渴爱、热爱的滋味是什么；四界的祸患是什么；如何才能从四界中解脱出来；这些问题，那么如来就无法证悟无上正等正觉，也就不能在人界、天界、魔界、梵天界等等众生所处的界中自称已经证悟了无上正等正觉的佛果，世间的普通人、出家人、修行人、天神、魔王、梵天王等等一切的众生也不会认可如来已经证悟了无上正等正觉，他们也不会接受如来的教导。</p><p>弟子们，就是因为如来证悟了地界、水界、火界、风界这四界的吸引力是什么；对四界渴爱、热爱的滋味是什么；四界的祸患是什么；如何才能从四界中解脱出来；这些问题，如来才能证悟无上正等正觉，才能在人界、天界、魔界、梵天界等等众生所处的界中自称已经证悟了无上正等正觉的佛果，世间的普通人、出家人、修行人、天神、魔王、梵天王等等一切的众生才会认可如来已经证悟了无上正等正觉，他们才会接受如来的教导。</p><p>弟子们，如来用开启的智慧去实践修行，向所有世间的众生证明了按着这样的方法去修行可以从世间生死轮回的烦恼和痛苦中永远的解脱出来，如来已经不会再被世间任何的事物所困扰、迷惑，如来内心已经不会再被世间一切的事物所束缚捆绑，如来已经解脱出来，如来知道自己这一世是最后一次出生在世间，如来以后不会再投生在世间，已经完全从世间的生死轮回中解脱出来。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',23)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
